import { IPitchDeckSlide } from "@/models/PitchDeckModel";

export interface DeckTemplate {
  id: string;
  name: string;
  description: string;
  industry: string;
  suggestedThemeId: string;
  slides: IPitchDeckSlide[];
}

function makeSlides(data: {
  company: string;
  tagline: string;
  elevator: string;
  problems: string[];
  problemBody: string;
  solutions: string[];
  solutionBody: string;
  marketBody: string;
  tam: string;
  sam: string;
  som: string;
  cagr: string;
  productBody: string;
  productBullets: string[];
  bizModelBody: string;
  bizModelBullets: string[];
  tractionBody: string;
  customers: string;
  revenue: string;
  growth: string;
  retention: string;
  competitionBody: string;
  competitionBullets: string[];
  teamBody: string;
  team: Array<{ name: string; role: string; bio: string }>;
  financialsBody: string;
  y1: string;
  y2: string;
  y3: string;
  margin: string;
  askBody: string;
  raising: string;
  round: string;
  runway: string;
  prevRaised: string;
  fundAllocation: string[];
  closingHeading: string;
  closingBody: string;
  closingCta: string;
}): IPitchDeckSlide[] {
  return [
    { slideType: "title", order: 0, heading: data.company, subheading: data.tagline, bodyText: data.elevator },
    { slideType: "problem", order: 1, heading: "The Problem", bodyText: data.problemBody, bulletPoints: data.problems },
    { slideType: "solution", order: 2, heading: "Our Solution", bodyText: data.solutionBody, bulletPoints: data.solutions },
    { slideType: "market", order: 3, heading: "Market Opportunity", bodyText: data.marketBody, metrics: [{ label: "TAM", value: data.tam }, { label: "SAM", value: data.sam }, { label: "SOM", value: data.som }, { label: "CAGR", value: data.cagr }] },
    { slideType: "product", order: 4, heading: "How It Works", bodyText: data.productBody, bulletPoints: data.productBullets },
    { slideType: "business_model", order: 5, heading: "Business Model", bodyText: data.bizModelBody, bulletPoints: data.bizModelBullets },
    { slideType: "traction", order: 6, heading: "Traction & Milestones", bodyText: data.tractionBody, metrics: [{ label: "Customers", value: data.customers }, { label: "ARR", value: data.revenue }, { label: "MoM Growth", value: data.growth }, { label: "NRR", value: data.retention }] },
    { slideType: "competition", order: 7, heading: "Why We Win", bodyText: data.competitionBody, bulletPoints: data.competitionBullets },
    { slideType: "team", order: 8, heading: "The Team", bodyText: data.teamBody, teamMembers: data.team },
    { slideType: "financials", order: 9, heading: "Financial Projections", bodyText: data.financialsBody, metrics: [{ label: "Year 1", value: data.y1 }, { label: "Year 2", value: data.y2 }, { label: "Year 3", value: data.y3 }, { label: "Gross Margin", value: data.margin }] },
    { slideType: "ask", order: 10, heading: `Raising ${data.raising}`, bodyText: data.askBody, metrics: [{ label: "Raising", value: data.raising }, { label: "Round", value: data.round }, { label: "Runway", value: data.runway }, { label: "Previously Raised", value: data.prevRaised }], bulletPoints: data.fundAllocation },
    { slideType: "closing", order: 11, heading: data.closingHeading, bodyText: data.closingBody, callToAction: data.closingCta },
  ];
}

